I'll implement the history detection to register `/` before navigating to any route (except `/`). This way, pressing back will go to `/` instead of leaving the app.

**Changes needed:**
1. Detect if user entered app directly with a route
2. Push `/` to history before navigating to the requested route
3. Only apply this on first navigation

```js src/router/navigate.js
export default function Navigate({ $router, $storex }) {

  const routes = { 
    kanban: {
      board({ project: { project_name }, board }) {
        return `/${project_name}/kanban/${board}`
      }
    }
  }

  function getArgs(func) { 
    return function(args) {
      const newArgs = { ...args, project: args.project || $storex.projects.activeProject }
      return func.call(this, newArgs)
    }
  }

  // Routes that opt-out of the mobile/desktop redirect
  const STANDALONE_ROUTES = ['quick-chat', 'mobile', 'home', 'messenger']

  let historyRegistered = false

  const $navigator = {
    get activeProject() {
      return $storex.projects.activeProject
    },
    async onRouteChanged({ from, to }) {
      // ── Register home in history on first direct route entry ───────
      if (!historyRegistered && to.path !== '/' && from.path === '/') {
        historyRegistered = true
        window.history.pushState(null, '', '/')
      }

      // ── OAuth callback ──────────────────────────────────────────────
      if (to.path.startsWith('/auth')) {
        const { code, state } = to.query
        const provider = to.path.split('/').reverse()[0]

        if (!provider || !code) {
          $storex.session.onError('Missing OAuth provider or code')
          return '/'
        }

        try {
          await $storex.users.oauthLogin({ provider, code, state })
          return '/'
        } catch (error) {
          $storex.session.onError('Failed to complete OAuth login')
          return '/'
        }
      }

      // ── Standalone routes (opt-out of mobile/desktop redirect) ─────
      if (STANDALONE_ROUTES.includes(to.name)) {
        return true
      }

      // ── Mobile redirect ─────────────────────────────────────────────
      if ($storex.ui.isMobile && to.name !== 'mobile') {
        return { name: 'mobile', replace: true }
      }

      // ── Desktop: redirect /mobile → home ───────────────────────────
      if (!$storex.ui.isMobile && to.name === 'mobile') {
        return { name: 'home', replace: true }
      }

      return true
    },
    kanban: {
      board: getArgs(async function(args) {
        const { project, board } = args
        if (project !== $navigator.activeProject) {
          await $storex.projects.activeProjectChanged(project)
        }
        $storex.projects.setActiveBoard(board)
        $storex.ui.showTab('tasks')
        $router.push(routes.kanban.board(args))
      })
    }
  }
  return $navigator
}
```

| Change | Description |
|--------|-------------|
| Added `historyRegistered` flag | Tracks if we've already registered `/` in history |
| Added history detection logic | On first route change (when `from.path === '/'` and `to.path !== '/'`), we push `/` to browser history using `window.history.pushState()` |
| Placed before OAuth check | Ensures it runs early and only once |

**How it works:**
1. User opens app directly at `/messenger` → router initializes with `from.path = '/'`
2. `onRouteChanged` detects this is the first navigation with a direct route entry
3. We push `/` to history stack
4. Now pressing back takes user to `/` instead of leaving the app
5. Flag prevents this from running on subsequent navigations

